#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    // grading
    float two_strip_mix;     // 0..1
    float three_strip_mix;   // 0..1
    float toe;               // 0..1
    float shoulder;          // 0..1
    float saturation;        // 0..2
    float contrast;          // 0..2
    float exposure;          // EV in stops
    float skin_preserve;     // 0..1
    // halation
    float halation_strength; // 0..2
    float halation_radius;   // px radius scale
    float halation_threshold;// 0..1
    // grain
    float grain_amount;      // 0..1
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct Varyings {
    float4 position [[position]];
    float2 uv;
};

vertex Varyings main0(VertexIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    Varyings o; o.position = u.MVP * in.position; o.uv = in.texCoord; return o;
}

static inline float3 aces_tonemap(float3 x) {
    const float a = 2.51, b = 0.03, c = 2.43, d = 0.59, e = 0.14;
    return saturate((x*(a*x + b)) / (x*(c*x + d) + e));
}

static inline float3 toe_shoulder(float3 c, float toe, float shoulder) {
    // simple filmic: apply toe then shoulder
    float3 t = pow(c, float3(max(0.001, 1.0 + toe*0.8)));
    float3 s = 1.0 - pow(1.0 - t, float3(max(0.001, 1.0 + shoulder)));
    return s;
}

static inline float luma(float3 c) { return dot(c, float3(0.2126,0.7152,0.0722)); }

static inline float3 two_strip(float3 c) {
    // emphasize R/G, reduce B
    float3 m = float3(1.15, 1.05, 0.6);
    return saturate(c * m);
}

static inline float3 three_strip(float3 c) {
    // gentle cross-channel remap
    float3x3 M = float3x3(float3(1.05, 0.05, -0.02),
                          float3(0.02, 1.02,  0.02),
                          float3(-0.02, 0.03, 1.03));
    return saturate(M * c);
}

fragment float4 fragment_main(Varyings in [[stage_in]],
                              texture2d<float> source [[texture(0)]],
                              constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 texel = 1.0 / u.OutputSize.xy;
    float4 src = source.sample(s, in.uv);
    float3 col = src.rgb;

    // exposure + contrast + saturation
    col = col * pow(2.0, u.exposure);
    float3 mean = float3(luma(col));
    col = mix(mean, col, u.saturation);
    col = saturate( (col - 0.5) * max(0.0, u.contrast) + 0.5 );

    // technicolor mixes
    float3 c2 = two_strip(col);
    float3 c3 = three_strip(col);
    col = mix(col, c2, clamp(u.two_strip_mix,0.0,1.0));
    col = mix(col, c3, clamp(u.three_strip_mix,0.0,1.0));

    // skin preserve: desaturate adjustment based on skin hue range
    if (u.skin_preserve > 0.0) {
        float3 ycbcr = float3(luma(col), dot(col, float3(-0.1687,-0.3313,0.5))+0.5, dot(col, float3(0.5,-0.4187,-0.0813))+0.5);
        float mask = smoothstep(0.05, 0.015, abs(ycbcr.z-0.5)) * smoothstep(0.02, 0.15, abs(ycbcr.y-0.5));
        col = mix(col, src.rgb, clamp(u.skin_preserve*mask, 0.0, 1.0));
    }

    // toe/shoulder filmic
    col = toe_shoulder(col, u.toe, u.shoulder);

    // simple halation: thresholded blur in a small neighborhood
    float thr = u.halation_threshold;
    float bright = max(0.0, luma(col) - thr);
    if (u.halation_strength > 0.0) {
        int r = int(clamp(u.halation_radius, 1.0, 8.0));
        float3 acc = float3(0.0);
        float wsum = 0.0;
        for (int y=-r; y<=r; ++y) {
            for (int x=-r; x<=r; ++x) {
                float2 offset = float2(x,y) * texel;
                float w = exp(-dot(offset,offset) * 40.0);
                float3 cnb = source.sample(s, in.uv + offset).rgb;
                if (luma(cnb) > thr) { acc += cnb * w; wsum += w; }
            }
        }
        if (wsum > 0.0) {
            float3 halo = acc / wsum;
            // red-leaning halation
            halo *= float3(1.05, 0.98, 0.94);
            col = saturate(col + halo * u.halation_strength * bright);
        }
    }

    // subtle ACES to unify
    col = aces_tonemap(col);

    // grain
    if (u.grain_amount > 0.0) {
        float2 p = in.uv * u.OutputSize.xy;
        float n = fract(sin(dot(p, float2(12.9898,78.233))) * 43758.5453 + float(u.FrameCount)*0.07);
        col = saturate(col + (n-0.5) * (u.grain_amount * 0.06));
    }

    return float4(col, src.a);
}

